&quot;) ## Dickey-Fuller = -5.452 cat(&quot; p-valor =&quot;, round(adf_diff$p.value, 4), &quot;
&quot;) ## p-valor = 0.01 cat(&quot; Conclusión:&quot;, ifelse(adf_diff$p.value &lt; 0.05, &quot;Estacionaria (p &lt; 0.05)&quot;, &quot;NO estacionaria&quot;), &quot;
&quot;) ## Conclusión: Estacionaria (p &lt; 0.05) autoplot(ipc_diff) + geom_hline(yintercept = 0, linetype = &quot;dashed&quot;, color = &quot;red&quot;) + labs(title = &quot;Serie Diferenciada del IPC Colombia&quot;, x = &quot;Año&quot;, y = &quot;Diferencia de variación mensual (pp)&quot;) + theme_minimal() Figure 4.1: Serie diferenciada del IPC. Tras la diferenciación, la serie oscila alrededor de cero sin tendencia visible, confirmando la estacionariedad. 4.5 Paso 3: Identificación de parámetros con ACF y PACF Las funciones de autocorrelación (ACF) y autocorrelación parcial (PACF) son la herramienta clave de la metodología Box-Jenkins para identificar los órdenes \(p\) y \(q\) del modelo: Si el ACF se trunca en el rezago \(q\) y el PACF decae gradualmente → modelo MA(\(q\)). Si el PACF se trunca en el rezago \(p\) y el ACF decae gradualmente → modelo AR(\(p\)). Si ambos decaen gradualmente → modelo ARMA(\(p,q\)) mixto. par(mfrow = c(2, 1), mar = c(4, 4, 3, 1)) acf(ipc_diff, lag.max = 36, main = &quot;ACF - Serie Diferenciada del IPC&quot;) pacf(ipc_diff, lag.max = 36, main = &quot;PACF - Serie Diferenciada del IPC&quot;) Figure 4.2: ACF y PACF de la serie diferenciada. Las barras que superan las bandas azules (intervalo de confianza al 95%) indican rezagos significativos. Interpretación del ACF y PACF: Observamos rezagos significativos en el ACF en los rezagos estacionales (12, 24), lo cual indica un componente estacional MA. El PACF muestra rezagos significativos en los primeros rezagos, sugiriendo un componente AR de orden bajo. Los picos en los rezagos múltiplos de 12 confirman la presencia de estacionalidad mensual, lo que sugiere que un modelo ARIMA estacional (SARIMA) será más apropiado. 4.6 Paso 4: Ajuste del modelo ARIMA 4.6.1 Selección automática con auto.arima() La función auto.arima() del paquete forecast evalúa múltiples combinaciones de \((p,d,q)(P,D,Q)_{12}\) y selecciona la que minimiza el criterio AICc: # Selección automática del modelo ARIMA modelo_auto &lt;- auto.arima(ipc_train, seasonal = TRUE, stepwise = FALSE, approximation = FALSE, trace = FALSE) cat(&quot;=== Modelo ARIMA Seleccionado ===

&quot;) ## === Modelo ARIMA Seleccionado === summary(modelo_auto) ## Series: ipc_train ## ARIMA(1,0,1)(2,1,0)[12] ## ## Coefficients: ## ar1 ma1 sar1 sar2 ## 0.7653 -0.2375 -0.5438 -0.3581 ## s.e. 0.0856 0.1403 0.0813 0.0769 ## ## sigma^2 = 0.04219: log likelihood = 24.65 ## AIC=-39.3 AICc=-38.9 BIC=-24.05 ## ## Training set error measures: ## ME RMSE MAE MPE MAPE MASE ACF1 ## Training set 0.00193594 0.1953692 0.1452042 -Inf Inf 0.6937782 0.004980781 # Mostrar coeficientes con significancia cat(&quot;
=== Coeficientes del Modelo ===

&quot;) ## ## === Coeficientes del Modelo === coef_test &lt;- coeftest(modelo_auto) print(coef_test) ## ## z test of coefficients: ## ## Estimate Std. Error z value Pr(&gt;|z|) ## ar1 0.765312 0.085566 8.9442 &lt; 2.2e-16 *** ## ma1 -0.237451 0.140253 -1.6930 0.09045 . ## sar1 -0.543780 0.081294 -6.6891 2.246e-11 *** ## sar2 -0.358119 0.076920 -4.6558 3.228e-06 *** ## --- ## Signif. codes: 0 &#39;***&#39; 0.001 &#39;**&#39; 0.01 &#39;*&#39; 0.05 &#39;.&#39; 0.1 &#39; &#39; 1 Interpretación del modelo: El modelo seleccionado por auto.arima() incorpora componentes autoregresivos (AR), de media móvil (MA) y posiblemente componentes estacionales. Cada coeficiente tiene un error estándar y un p-valor que indica su significancia estadística. Los coeficientes con p-valor &lt; 0.05 son estadísticamente significativos. 4.6.2 Modelos candidatos alternativos Para verificar que la selección automática es robusta, ajustamos manualmente algunos modelos candidatos y comparamos sus criterios de información: # Modelo 1: ARIMA sin componente estacional m1 &lt;- Arima(ipc_train, order = c(1, 1, 1)) # Modelo 2: ARIMA con estacionalidad básica m2 &lt;- Arima(ipc_train, order = c(1, 1, 1), seasonal = list(order = c(1, 0, 1), period = 12)) # Modelo 3: ARIMA con mayor orden m3 &lt;- Arima(ipc_train, order = c(2, 1, 2), seasonal = list(order = c(1, 0, 1), period = 12)) # Comparar AICc comparacion &lt;- data.frame( Modelo = c(paste(&quot;Auto:&quot;, modelo_auto$arma[1], &quot;,&quot;, modelo_auto$arma[6], &quot;,&quot;, modelo_auto$arma[2]), &quot;ARIMA(1,1,1)&quot;, &quot;ARIMA(1,1,1)(1,0,1)[12]&quot;, &quot;ARIMA(2,1,2)(1,0,1)[12]&quot;), AIC = round(c(modelo_auto$aic, m1$aic, m2$aic, m3$aic), 2), AICc = round(c(modelo_auto$aicc, m1$aicc, m2$aicc, m3$aicc), 2), BIC = round(c(modelo_auto$bic, m1$bic, m2$bic, m3$bic), 2) ) knitr::kable(comparacion, caption = &quot;Comparación de criterios de información entre modelos candidatos&quot;, align = &quot;lccc&quot;) Table 4.1: Comparación de criterios de información entre modelos candidatos Modelo AIC AICc BIC Auto: 1 , 0 , 1 -39.30 -38.90 -24.05 ARIMA(1,1,1) -4.11 -3.96 5.24 ARIMA(1,1,1)(1,0,1)[12] -68.02 -67.64 -52.43 ARIMA(2,1,2)(1,0,1)[12] -64.79 -64.08 -42.96 El modelo con menor AICc es el preferido, ya que balancea bondad de ajuste con parsimonia (penaliza la complejidad). 4.7 Paso 5: Verificación de supuestos (Análisis de residuos) Un modelo ARIMA bien ajustado debe producir residuos que se comporten como ruido blanco: sin autocorrelación, con media cero y varianza constante. Verificamos estos supuestos: checkresiduals(modelo_auto) Figure 4.3: Diagnóstico de residuos del modelo ARIMA: serie temporal, ACF e histograma. Los residuos deben parecer ruido blanco. ## ## Ljung-Box test ## ## data: Residuals from ARIMA(1,0,1)(2,1,0)[12] ## Q* = 53.216, df = 20, p-value = 7.553e-05 ## ## Model df: 4. Total lags used: 24 # Prueba de Ljung-Box residuales &lt;- residuals(modelo_auto) lb_test &lt;- Box.test(residuales, lag = 24, type = &quot;Ljung-Box&quot;) cat(&quot;=== Prueba de Ljung-Box ===
&quot;) ## === Prueba de Ljung-Box === cat(&quot; H0: Los residuos son ruido blanco (no hay autocorrelación)
&quot;) ## H0: Los residuos son ruido blanco (no hay autocorrelación) cat(&quot; Estadístico X²:&quot;, round(lb_test$statistic, 4), &quot;
&quot;) ## Estadístico X²: 53.2162 cat(&quot; p-valor:&quot;, round(lb_test$p.value, 4), &quot;
&quot;) ## p-valor: 5e-04 cat(&quot; Conclusión:&quot;, ifelse(lb_test$p.value &gt; 0.05, &quot;No se rechaza H0: residuos sin autocorrelación significativa. ✓&quot;, &quot;Se rechaza H0: existe autocorrelación residual. ✗&quot;), &quot;

&quot;) ## Conclusión: Se rechaza H0: existe autocorrelación residual. ✗ # Prueba de normalidad sw_test &lt;- shapiro.test(residuales) cat(&quot;=== Prueba de Shapiro-Wilk ===
&quot;) ## === Prueba de Shapiro-Wilk === cat(&quot; H0: Los residuos siguen distribución normal
&quot;) ## H0: Los residuos siguen distribución normal cat(&quot; Estadístico W:&quot;, round(sw_test$statistic, 4), &quot;
&quot;) ## Estadístico W: 0.9782 cat(&quot; p-valor:&quot;, round(sw_test$p.value, 4), &quot;
&quot;) ## p-valor: 0.0095 cat(&quot; Conclusión:&quot;, ifelse(sw_test$p.value &gt; 0.05, &quot;No se rechaza H0: residuos normales. ✓&quot;, &quot;Se rechaza H0: residuos no normales. ✗
 (Nota: la no normalidad no invalida el modelo,
 pero afecta la precisión de los intervalos de confianza.)&quot;), &quot;
&quot;) ## Conclusión: Se rechaza H0: residuos no normales. ✗ ## (Nota: la no normalidad no invalida el modelo, ## pero afecta la precisión de los intervalos de confianza.) qqnorm(residuales, main = &quot;Q-Q Plot de Residuos del Modelo ARIMA&quot;) qqline(residuales, col = &quot;red&quot;, lwd = 2) Figure 4.4: Gráfico Q-Q de los residuos del modelo ARIMA. Los puntos deben seguir la línea diagonal si los residuos son normales. 4.8 Detección de puntos de cambio y valores atípicos La serie del IPC experimentó cambios estructurales importantes, especialmente durante el período inflacionario 2021-2023. Identificamos estos puntos de cambio y valores atípicos: library(changepoint) # Detectar puntos de cambio en la media mval &lt;- cpt.mean(ipc_train, method = &quot;PELT&quot;) cat(&quot;=== Puntos de Cambio en la Media ===
&quot;) ## === Puntos de Cambio en la Media === cat(&quot; Posiciones:&quot;, cpts(mval), &quot;
&quot;) ## Posiciones: # Convertir posiciones a fechas aproximadas for (i in seq_along(cpts(mval))) { pos &lt;- cpts(mval)[i] anio &lt;- 2010 + (pos - 1) %/% 12 mes_num &lt;- ((pos - 1) %% 12) + 1 meses_nombre &lt;- c(&quot;Ene&quot;,&quot;Feb&quot;,&quot;Mar&quot;,&quot;Abr&quot;,&quot;May&quot;,&quot;Jun&quot;, &quot;Jul&quot;,&quot;Ago&quot;,&quot;Sep&quot;,&quot;Oct&quot;,&quot;Nov&quot;,&quot;Dic&quot;) cat(&quot; Punto&quot;, i, &quot;:&quot;, meses_nombre[mes_num], anio, &quot;(observación&quot;, pos, &quot;)
&quot;) } plot(mval, type = &quot;l&quot;, xlab = &quot;Observación&quot;, ylab = &quot;Variación mensual (%)&quot;, cpt.col = &quot;blue&quot;, cpt.width = 3) title(&quot;Puntos de Cambio en la Media - IPC Colombia&quot;) Figure 4.5: Detección de puntos de cambio en la media de la serie del IPC. Las líneas verticales indican cambios estructurales identificados. Interpretación: Los puntos de cambio detectados coinciden con eventos macroeconómicos relevantes en Colombia. El cambio más notable ocurre alrededor de 2021-2022, cuando la inflación se aceleró significativamente debido a disrupciones en cadenas de suministro, aumento de precios de commodities y presiones de demanda post-pandemia. 4.9 Paso 6: Pronóstico con el modelo ARIMA 4.9.1 Pronóstico sobre el conjunto de prueba Evaluamos la capacidad predictiva del modelo sobre el período 2024-2025: # Pronóstico para el período de prueba arima_forecast_test &lt;- forecast(modelo_auto, h = 24) autoplot(arima_forecast_test) + autolayer(ipc_test, series = &quot;Datos reales&quot;) + labs(title = paste(&quot;Pronóstico&quot;, modelo_auto, &quot;- IPC Colombia&quot;), subtitle = &quot;Entrenamiento: 2010-2023 | Prueba: 2024-2025&quot;, x = &quot;Año&quot;, y = &quot;Variación mensual (%)&quot;) + theme_minimal() + theme(legend.position = &quot;bottom&quot;) Figure 4.6: Pronóstico ARIMA vs. datos reales del período de prueba (2024-2025), con intervalos de confianza al 80% y 95%. 4.9.2 Métricas de error # Calcular métricas de error error &lt;- ipc_test - arima_forecast_test$mean mae &lt;- mean(abs(error)) rmse &lt;- sqrt(mean(error^2)) no_cero &lt;- which(ipc_test != 0) mape &lt;- mean(abs(error[no_cero] / ipc_test[no_cero])) * 100 cat(&quot;=== Métricas de Error - Conjunto de Prueba ===

&quot;) ## === Métricas de Error - Conjunto de Prueba === cat(&quot; MAE =&quot;, round(mae, 4), &quot;
&quot;) ## MAE = 0.5212 cat(&quot; RMSE =&quot;, round(rmse, 4), &quot;
&quot;) ## RMSE = 0.6652 cat(&quot; MAPE =&quot;, round(mape, 2), &quot;%
&quot;) ## MAPE = 61.3 % 4.10 Comparación: ARIMA vs. Holt-Winter Comparamos el desempeño del modelo ARIMA con los modelos de suavizamiento exponencial del capítulo anterior: # Reajustar Holt-Winter para comparación hw_add &lt;- hw(ipc_train, seasonal = &quot;additive&quot;, h = 24) hw_damped &lt;- hw(ipc_train, seasonal = &quot;additive&quot;, damped = TRUE, h = 24) ets_auto &lt;- ets(ipc_train) ets_fc &lt;- forecast(ets_auto, h = 24) # Función de métricas calc_met &lt;- function(real, pred, nombre) { e &lt;- real - pred no_z &lt;- which(real != 0) data.frame( Modelo = nombre, MAE = round(mean(abs(e)), 4), RMSE = round(sqrt(mean(e^2)), 4), MAPE = round(mean(abs(e[no_z] / real[no_z])) * 100, 2) ) } comp &lt;- rbind( calc_met(ipc_test, hw_add$mean, &quot;HW Aditivo&quot;), calc_met(ipc_test, hw_damped$mean, &quot;HW Aditivo Amortiguado&quot;), calc_met(ipc_test, ets_fc$mean, paste(&quot;ETS&quot;, ets_auto$method)), calc_met(ipc_test, arima_forecast_test$mean, paste(&quot;ARIMA&quot;, paste0(&quot;(&quot;, paste(modelo_auto$arma[c(1,6,2)], collapse=&quot;,&quot;), &quot;)&quot;))) ) knitr::kable(comp, caption = &quot;Comparación de modelos: Holt-Winter vs. ARIMA en el conjunto de prueba&quot;, align = &quot;lccc&quot;) Table 4.2: Comparación de modelos: Holt-Winter vs. ARIMA en el conjunto de prueba Modelo MAE RMSE MAPE HW Aditivo 0.5189 0.6442 62.09 HW Aditivo Amortiguado 0.4495 0.5774 53.98 ETS ETS(A,N,A) 0.4490 0.5782 53.86 ARIMA (1,0,1) 0.5212 0.6652 61.30 autoplot(window(ipc_ts, start = c(2022, 1))) + autolayer(arima_forecast_test, series = &quot;ARIMA&quot;, PI = FALSE) + autolayer(hw_add, series = &quot;HW Aditivo&quot;, PI = FALSE) + autolayer(hw_damped, series = &quot;HW Amortiguado&quot;, PI = FALSE) + labs(title = &quot;Comparación de Pronósticos - IPC Colombia&quot;, x = &quot;Año&quot;, y = &quot;Variación mensual (%)&quot;) + theme_minimal() + theme(legend.position = &quot;bottom&quot;) Figure 4.7: Comparación visual de pronósticos: ARIMA vs. Holt-Winter vs. datos reales. 4.10.1 Pronóstico final para 2026 Reajustamos el modelo ARIMA con toda la serie disponible (2010-2025) para generar el pronóstico final: # Reajustar con toda la serie modelo_final &lt;- auto.arima(ipc_ts, seasonal = TRUE, stepwise = FALSE, approximation = FALSE) cat(&quot;=== Modelo Final (toda la serie) ===
